options(warn = 2)
stopifnot(getRversion() == "4.6.1")
root <- normalizePath(getwd(), mustWork = TRUE)
out <- "/private/tmp/order72k-s2-recovery.FRG4Vi"
w <- "audit/manuscript_nature_health/revision_2026_09_11/consolidated_display_repair_order72k"
d <- "audit/report_harmonization/report018_order72k_non_s5_integration_dispatch"
full <- function(p) ifelse(startsWith(p, "/"), p, file.path(root, p))
sha <- function(p) digest::digest(file = p, algo = "sha256", serialize = FALSE)
pin <- function(p) {
  f <- full(p)
  stopifnot(file.exists(f), !dir.exists(f), Sys.readlink(f) == "")
  data.frame(path = p, sha256 = sha(f), bytes = unname(file.info(f)$size))
}
checks <- list()
ck <- function(id, x, detail) {
  checks[[length(checks) + 1L]] <<- data.frame(check = id, pass = isTRUE(x), detail = detail)
  if (!isTRUE(x)) stop(id, ": ", detail)
}
orig <- read.csv(full(file.path(w, "stopped_final_checks/original_429_identities.csv")), stringsAsFactors = FALSE)
ck("original_inventory_shape", nrow(orig) == 429L && all(orig$final_exact), "Stored 429-row preservation check")
owner_path <- file.path(w, "stopped_owner_manifest.csv")
ck("owner_manifest_sha", sha(full(owner_path)) == "445ba04dd59cd3ef1be2d1d7bc625c8b4f8ce3852b97d48a9d80f86c3f667d25", "Exact sealed 263-row owner manifest")
owner <- read.csv(full(owner_path), stringsAsFactors = FALSE)
ck("owner_manifest_shape", nrow(owner) == 263L && !anyDuplicated(owner$path) && !owner_path %in% owner$path, "Unique non-circular owner manifest")
owner_obs <- do.call(rbind, lapply(owner$path, pin))
owner_exact <- owner$sha256 == owner_obs$sha256 & owner$bytes == owner_obs$bytes
ck("owner_manifest_members", all(owner_exact), "263/263 owner stopped-state members exact")
write.csv(data.frame(owner[,c("path","sha256","bytes")], observed_sha256 = owner_obs$sha256, observed_bytes = owner_obs$bytes, pass = owner_exact), file.path(out, "owner_manifest_rehash.csv"), row.names = FALSE)
ck("owner_stop_record", sha(full(file.path(w, "stopped_return.md"))) == "7e45b0b3398f9c3d6abcbb8ef6880329a2f48f1390b032ed6ba6e86804dc9d46", "Final stopped return and visual lease release reproduced")
hashes <- vapply(full(orig$path), sha, character(1))
ck("original_inventory_rehash", all(hashes == orig$expected_sha256) && all(file.info(full(orig$path))$size == orig$bytes), "All 429 original authority/input rows remain exact")
write.csv(data.frame(path = orig$path, expected_sha256 = orig$expected_sha256, observed_sha256 = hashes, exact = hashes == orig$expected_sha256), file.path(out, "original_rehash.csv"), row.names = FALSE)
