ck("launch_stop", all(vapply(c("browserType.launch", "Target page, context or browser has been closed", "kill EPERM", "SIGABRT", "pid=36917"), function(s) grepl(s, log, fixed = TRUE), logical(1))), "Launch failure and process-exit record, not a reported URL-policy rejection")
ck("no_attempt2_output", !file.exists(full(file.path(w, "capture_s2_attempt2"))), "Failed capture destination does not exist")
ck("no_attempt3_output", !file.exists(full(file.path(w, "capture_s2_attempt3"))), "Final adjustment destination is unused")
h <- full(file.path(w, "helpers/capture_word_tables.mjs"))
ck("unchanged_correction_helper", sha(h) == "8dd21ba1d978e36d1cafa0669b7c2456306b66e996f013f44b86ebc2549e0174", "Current helper equals exact retained S2 correction postimage")
ht <- paste(readLines(h, warn = FALSE), collapse = "\n")
ck("same_browser_and_subset", all(vapply(c('"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"', 'executablePath: chromePath', 'captureSubset !== "only-s2"', 'activeSpecs.filter((s) => !captureSubset || s.key === "supp_table_s2")', 'for (const [key, sourcePath] of [])', 'Capture destination already exists; no implicit retry'), function(s) grepl(s, ht, fixed = TRUE), logical(1))), "Same installed Chrome, only-s2 subset, unique output, figure capture disabled")
served <- jsonlite::fromJSON(full(file.path(w, "server_preflight.json")))
session <- jsonlite::fromJSON(full(file.path(w, "server_session.json")))
ck("old_server_closed", session$status == "closed" && session$host == "127.0.0.1" && session$port == 58005 && session$pid == 35776, "Old lifecycle closed at 2026-09-11T19:32:18Z")
files <- served$files
ck("served_source_copy_exact", all(vapply(files$source, sha, character(1)) == files$sha256) && all(vapply(files$served, sha, character(1)) == files$sha256), paste(nrow(files), "rendered source/copy pairs exact"))
all_paths <- list.files(served$root, recursive = TRUE, all.files = TRUE, no.. = TRUE, include.dirs = TRUE, full.names = TRUE)
ck("served_no_symlinks", all(Sys.readlink(all_paths) == ""), "No symlink under existing minimal preview")
