ck("frozen_table_source", sha(full(table_source)) == "6832c791ed3ebcf8895106dafe68c7c5118a12a74e37aacdeb8a84b02d9bfe97", "Accepted S2 table fragment exact")
html <- full(file.path(w, "preview_attempt1/main/ZaunerEtAl2026_NatHealth_phase3_brown.html"))
dom <- xml2::read_html(html)
ep <- xml2::xml_find_all(dom, "//*[@id='tbl-near-eye-metrics']")
ck("unique_s2_endpoint", length(ep) == 1L, "One served S2 endpoint")
tbl <- xml2::xml_find_all(ep, ".//table")
if (xml2::xml_name(ep) == "table") tbl <- ep
rows <- xml2::xml_find_all(tbl, ".//tbody/tr")
widths <- vapply(rows, function(r) length(xml2::xml_find_all(r, "./th|./td")), integer(1))
