captures <- file.path(w, "capture_attempt1", list.files(full(file.path(w, "capture_attempt1")), recursive = TRUE, all.files = TRUE, no.. = TRUE))
capture_pins <- do.call(rbind, lapply(captures, pin))
write.csv(capture_pins, file.path(out, "completed_capture_pins.csv"), row.names = FALSE)
ck("reusable_capture_files", all(file.exists(full(file.path(w, "capture_attempt1", c("supp_table_s5_part_01.png", "supp_table_s6_part_01.png", "supp_table_s10_part_01.png", "supp_table_s10_part_02.png"))))), "All completed S5/S6/S10 PNG parts exist")
