qmds <- c(file.path(w, "project/ZaunerEtAl2026_NatHealth_phase3_brown.qmd"), file.path(w, "project/supplementary_information_outline.qmd"), "audit/manuscript_nature_health/consolidated_display_repair_2026_09_11/integration_candidate_order72k/project/selection.qmd")
paths <- sort(unique(c(extra, qmds, table_source, captures, files$source, files$served, runtime, owner_path, file.path(w,c("stopped_return.md","trial_ledger.csv")), file.path(d, c("capture_s2_environment_stop.md", "lua_dependency_closure_addendum.md", "lua_dependency_closure_pins.csv")), "audit/report_harmonization/owner_orders/72k_non_s5_svg_and_table_preview_integration.md", "audit/report_harmonization/owner_orders/72k_environment_cache_recovery_001.md")))
