write.csv(pins, file.path(out, "input_pins.csv"), row.names = FALSE)
write.csv(do.call(rbind, checks), file.path(out, "checks.csv"), row.names = FALSE)
writeLines(c(capture.output(sessionInfo()), paste("digest", packageVersion("digest")), paste("jsonlite", packageVersion("jsonlite")), paste("xml2", packageVersion("xml2"))), file.path(out, "session.txt"))
cat(sprintf("ORDER72K_S2_STOP_AUDIT=PASS checks=%d original=429/429 inputs=%d captures=%d served=%d R=%s browser_runs=0\n", length(checks), nrow(pins), nrow(capture_pins), nrow(files), getRversion()))
print(pins[pins$path %in% c(file.path(w, "helpers/capture_word_tables.mjs"), file.path(w, "capture_s2_attempt2_command.json"), file.path(w, "capture_s2_attempt2.log")), ], row.names = FALSE)
